<script>
    function SafeGetValue(obj, path, d = ["N/A", ""]) { let k = path.split('.'), c = obj; for (let i of k) { if (c === undefined || c === null || typeof c !== 'object' || !c.hasOwnProperty(i)) return d; c = c[i]; } return (c === undefined || c === null) ? d : (Array.isArray(c) ? c : [c, ""]); }
    function parseValue(v) { return String(v).split(/ \| /).map(p => p.trim())[0]; }
    function updateDisplay(id, val) { const el = document.getElementById(id); if (el) el.innerText = val; }
    function animateProgressBar(bar, percentage) { if(bar) { bar.style.width = '0%'; requestAnimationFrame(() => { setTimeout(() => { bar.style.width = `${percentage}%` }, 50); }); } }
    function updateProgressBar(barId, valueId, rawVal, min, max) { let val = rawVal[0] || (min !== undefined ? `${min}` : "0"); const numericVal = parseFloat(parseValue(val)); const textVal = String(val).replace(/->/g, ' → '); updateDisplay(valueId, textVal); const pct = max > min ? ((Math.max(min, Math.min(max, numericVal)) - min) / (max - min)) * 100 : 0; animateProgressBar(document.getElementById(barId), pct); }
    function updateTrait(name, lvArr, progArr) { updateDisplay(`trait-${name}-level`, lvArr[0] || '0'); animateProgressBar(document.getElementById(`trait-${name}-bar`), parseFloat(parseValue(progArr[0])) || 0); }
    function updateCurriculum(stage, day, time) {
        ['1','2','3'].forEach(s => { const el = document.getElementById(`curriculum-stage-${s}`); if(el) el.style.display = (String(s) === String(stage)) ? 'block' : 'none'; });
        const dayMap = {'星期一':'mon', '星期二':'tue', '星期三':'wed', '星期四':'thu', '星期五':'fri', '星期六':'sat', '星期日':'sun'};
        const timeMap = {'清晨':'am', '上午':'am', '午后':'pm', '傍晚':'pm', '夜晚': 'pm', '午夜': 'pm'};
        const dayShort = dayMap[parseValue(day)];
        const timeShort = timeMap[parseValue(String(time)).split(' ')[0]];
        if (!dayShort) return;
        let targetId = `s${stage}-${dayShort}`;
        const isWeekendStage13 = (stage == 1 || stage == 3) && ['sat', 'sun'].includes(dayShort);
        const isSpecialSunday = (stage == 2 && dayShort === 'sun');
        if (isWeekendStage13) { targetId += '-all'; } else if (isSpecialSunday && timeShort) { targetId += `-${timeShort}`; } else if (timeShort) { targetId += `-${timeShort}`; }
        [...document.querySelectorAll('.today-course')].forEach(c => c.classList.remove('today-course'));
        const currentCell = document.getElementById(targetId);
        if(currentCell) { currentCell.classList.add('today-course'); }
        else { const fallbackCell = document.getElementById(`s${stage}-${dayShort}-pm`) || document.getElementById(`s${stage}-${dayShort}-am`); if(fallbackCell) fallbackCell.classList.add('today-course'); }
    }

    function toggleSection(el) { const c = el.nextElementSibling, a = el.querySelector('.arrow'); if (!c || !a) return; (c.classList.toggle('expanded')); (a.style.transform = c.classList.contains('expanded') ? 'rotate(180deg)' : 'rotate(0deg)'); }
    function toggleSubcategory(el) { const c = el.nextElementSibling, a = el.querySelector('.subcategory-arrow'); if (!c || !a) return; c.classList.toggle('expanded'); a.style.transform = c.classList.contains('expanded') ? 'rotate(180deg)' : 'rotate(0deg)'; }

    function renderSkills(containerId, skillsData) {
        const container = document.getElementById(containerId);
        if (!container || !skillsData) return;
        container.innerHTML = '';

        const skillGroupConfigs = {
            '身体开发': {
                '口腔开发': ['初级口侍', '深喉技巧', '魔力吸收', '言灵侍奉'],
                '乳部开发': ['初级敏感', '快感耐受', '泌乳诱导'],
                '花穴与子宫': ['初红献祭', '高潮耐受', '子宫快感开发', '多重高潮控制', '孕育适应'],
                '后庭开发': ['初级容纳', '内部快感认知', '前列腺刺激', '禁断愉悦'],
                '体液调和': ['唾液甜化', '爱液增幅', '体香媚药化']
            },
            '精神隶属': {
                '灵魂契约': skillsData['精神隶属'] ? skillsData['精神隶属'].map(s => s.name) : []
            },
            '侍奉礼仪': {
                '初级侍奉': ['茶道入门', '口舌技巧·卷舌', '精油按摩', '手部爱抚·魔力流转', '古典舞步', '高难体位解锁'],
                '高级侍奉': ['双穴侍奉协调', '榨精特训', '淫纹绘制'],
                '终极侍奉': ['灵魂共鸣侍奉', '梦境潜入', '生命共享契约']
            }
        };

        for (const categoryName in skillGroupConfigs) {
            if (!skillsData.hasOwnProperty(categoryName)) continue;

            const mainCategoryTitle = document.createElement('h3');
            mainCategoryTitle.className = 'skill-main-category';
            mainCategoryTitle.innerText = categoryName;
            container.appendChild(mainCategoryTitle);

            const subcategories = skillGroupConfigs[categoryName];
            for (const subcatName in subcategories) {
                const categorySkills = skillsData[categoryName];
                const subCategorySkillNames = subcategories[subcatName];
                const subCategorySkills = categorySkills.filter(s => subCategorySkillNames.includes(s.name));

                if (subCategorySkills.length === 0) continue;

                const subcatElement = document.createElement('div');
                subcatElement.className = 'skill-subcategory';
                const header = document.createElement('div');
                header.className = 'skill-subcategory-header';
                header.onclick = function() { toggleSubcategory(this); };
                header.innerHTML = `<span>${subcatName}</span><span class="subcategory-arrow">▼</span>`;
                const list = document.createElement('ul');
                list.className = 'skill-subcategory-list';

                subCategorySkills.forEach(skill => {
                    const li = document.createElement('li');
                    li.className = 'skill-item ' + (skill.status === '已掌握' ? 'learned' : 'locked');
                    li.innerHTML = `<span class="skill-name">${skill.name}</span><span class="skill-status">${skill.status}</span>`;
                    list.appendChild(li);
                });

                subcatElement.appendChild(header);
                subcatElement.appendChild(list);
                container.appendChild(subcatElement);
            }
        }
    }

    async function initDisplay() {
        try {
            const m = await getChatMessages(getCurrentMessageId());
            if (!m || !m[0]?.data) throw new Error("无法加载状态数据");
            const d = m[0].data.stat_data || m[0].data.display_data;
            if (!d) throw new Error("角色数据缺失");
            const u = "<user>", s = "时幼微", w = "世界";

            updateDisplay('world-date', (SafeGetValue(d, `${w}.当前日期`)[0] || '') + ' ' + (SafeGetValue(d, `${w}.当前星期`)[0] || ''));
            updateDisplay('shiyouwei-thoughts', SafeGetValue(d, `${s}.当前所想`)[0]);
            updateDisplay('user-thoughts', SafeGetValue(d, `${u}.内心想法`)[0]);
            updateProgressBar('user-training-bar', 'user-training-value', SafeGetValue(d, `${u}.精神状态数值.调教值`), 0, 100);
